<##
.SYNOPSIS
  Creates one immutable candidate Enterprise Skill release without installing it.
##>
param([Parameter(Mandatory=$true)][string]$SkillId,[Parameter(Mandatory=$true)][string]$SkillVersion,[Parameter(Mandatory=$true)][string]$ArtifactRef,[Parameter(Mandatory=$true)][ValidatePattern('^sha256:[a-fA-F0-9]{64}$')][string]$IntegrityHash,[Parameter(Mandatory=$true)][string]$SourceRef,[Parameter(Mandatory=$true)][string]$OwnerId,[Parameter(Mandatory=$true)][string]$TenantId,[Parameter(Mandatory=$true)][string]$OrganizationId,[Parameter(Mandatory=$true)][string]$ProjectId,[Parameter(Mandatory=$true)][ValidateSet('public','internal_sanitized','confidential_reference_only')][string]$Classification,[Parameter(Mandatory=$true)][string]$DeclaredCapabilities,[Parameter(Mandatory=$true)][string]$DeclaredTools,[Parameter(Mandatory=$true)][ValidateSet('L1','L2','L3','L4')][string]$RiskLevel,[Parameter(Mandatory=$true)][string]$RollbackRef,[Parameter(Mandatory=$true)][string]$TaskId,[Parameter(Mandatory=$true)][string]$GrantId,[Parameter(Mandatory=$true)][string]$TraceId,[string]$OutputPath='',[switch]$PassThru)
$ErrorActionPreference='Stop';$projectRoot=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;$root=[IO.Path]::GetFullPath((Join-Path $projectRoot '.qianlima/run-traces/enterprise-skills/releases')).TrimEnd('\','/')+[IO.Path]::DirectorySeparatorChar;function Emit([hashtable]$Value,[int]$Code=0){if($PassThru){$Value|ConvertTo-Json -Depth 12}else{$Value|Format-List};if($Code-ne0){exit $Code}};$ref='^(?:[a-z][a-z0-9+.-]*://|sha256:)[^\s]+$';if($ArtifactRef-notmatch$ref-or$SourceRef-notmatch$ref-or$RollbackRef-notmatch$ref){Emit ([ordered]@{status='blocked';reason='reference_only_skill_metadata_required';release_written=$false}) 1};$capabilities=@($DeclaredCapabilities-split';'|Where-Object{$_});$tools=@($DeclaredTools-split';'|Where-Object{$_});if(-not$capabilities.Count-or-not$tools.Count){Emit ([ordered]@{status='blocked';reason='declared_capabilities_and_tools_required';release_written=$false}) 1};$releaseId=$SkillId+'@'+$SkillVersion;if([string]::IsNullOrWhiteSpace($OutputPath)){$safe=$releaseId-replace'[^A-Za-z0-9._-]','_';$OutputPath=Join-Path $root "$safe.json"};$full=[IO.Path]::GetFullPath($OutputPath);if(-not$full.StartsWith($root,[StringComparison]::OrdinalIgnoreCase)){Emit ([ordered]@{status='blocked';reason='skill_release_outside_governed_root';release_written=$false}) 1};if(Test-Path -LiteralPath $full){Emit ([ordered]@{status='blocked';reason='skill_release_already_exists';release_written=$false}) 1};$release=[ordered]@{schema_version=1;release_id=$releaseId;skill_id=$SkillId;skill_version=$SkillVersion;artifact_ref=$ArtifactRef;integrity_hash=$IntegrityHash.ToLowerInvariant();source_ref=$SourceRef;owner_id=$OwnerId;tenant_id=$TenantId;organization_id=$OrganizationId;project_id=$ProjectId;classification=$Classification;declared_capabilities=$capabilities;declared_tools=$tools;risk_level=$RiskLevel;rollback_ref=$RollbackRef;status='candidate';created_at=[DateTime]::UtcNow.ToString('o');installed=$false;execution_authority=$false;tool_authority=$false;data_scope_authority=$false;production_authority=$false};New-Item -ItemType Directory -Path (Split-Path -Parent $full) -Force|Out-Null;[IO.File]::WriteAllText($full,($release|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));$audit=Join-Path $PSScriptRoot 'append-enterprise-audit-event.ps1';try{& $audit -EventType skill_candidate_created -Decision accept -TenantId $TenantId -OrganizationId $OrganizationId -UserId $OwnerId -AgentId 'skill-governor' -AgentVersion 'skill-lifecycle-v1' -TaskId $TaskId -GrantId $GrantId -TraceId $TraceId -PolicyVersion '2.14.0' -ArtifactRefs ('skill-release://'+$releaseId) -EvidenceRefs @($SourceRef,$IntegrityHash) -PassThru|Out-Null}catch{Emit ([ordered]@{status='blocked';reason='skill_release_audit_failed';release_written=$true;release_path=$full}) 1};Emit ([ordered]@{status='candidate';release_id=$releaseId;release_path=$full;release_written=$true;installed=$false;execution_authority=$false;external_calls=$false})
